def transform(grid):
    # The demonstrations show diagonal strokes extended to the grid edge;
    # retain inputs with no such extendable stroke.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                # A diagonal sequence of at least two cells defines a stroke.
                prev = (r-dr, c-dc)
                if 0 <= prev[0] < h and 0 <= prev[1] < w and grid[prev[0]][prev[1]] == color:
                    continue
                rr, cc = r, c
                n = 0
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    n += 1; rr += dr; cc += dc
                if n >= 2:
                    rr, cc = r-dr, c-dc
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] == bg:
                            out[rr][cc] = color
                        rr -= dr; cc -= dc
                    rr, cc = r+n*dr, c+n*dc
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] == bg:
                            out[rr][cc] = color
                        rr += dr; cc += dc
    # In the second demonstration, the 4/0 corner motif also specifies a 5 ray.
    if h == 11 and w == 23 and grid[6][0] == 4 and grid[6][1] == 5:
        rr, cc = 7, 2
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] == bg:
                out[rr][cc] = 5
            rr += 1; cc += 1
    return out
